1	// Probe helper: run the reference Python executable over a JSON corpus and show
2	// its exact output. Lets discovery agents study behaviour without fighting shell
3	// quoting.
4	//
5	// Usage:  node /workspace/harness/probe.mjs <corpus.json>
6	//         node /workspace/harness/probe.mjs --inline '["SELECT 1; SELECT 2"]'
7	//
8	// Entries are either a string (argv becomes ["--a", s]) or an array of raw argv.
9	
10	import { spawnSync } from 'node:child_process';
11	import { readFileSync } from 'node:fs';
12	
13	const EXE = '/workspace/dataset/test2_executable';
14	const args = process.argv.slice(2);
15	
16	let entries;
17	if (args[0] === '--inline') entries = JSON.parse(args[1]);
18	else entries = JSON.parse(readFileSync(args[0], 'utf8'));
19	
20	for (const entry of entries) {
21	  const argv = Array.isArray(entry) ? entry.map(String) : ['--a', String(entry)];
22	  const r = spawnSync(EXE, argv, { encoding: 'utf8', maxBuffer: 1 << 28 });
23	  console.log('IN   : ' + JSON.stringify(argv));
24	  console.log('OUT  : ' + JSON.stringify(r.stdout ?? ''));
25	  if (r.stderr) console.log('ERR  : ' + JSON.stringify(r.stderr));
26	  console.log('CODE : ' + r.status);
27	  console.log('');
28	}
29

