import { writeFileSync } from 'node:fs';
const C = (n) => String.fromCharCode(n);
const out = [];
// whitespace classification probes: does <X> after ';' get absorbed (whitespace) or terminate (newline) or start a new stmt?
const cands = [0x09,0x0a,0x0b,0x0c,0x0d,0x1c,0x1d,0x1e,0x1f,0x20,0x85,0xa0,0x1680,0x2000,0x2028,0x2029,0x202f,0x205f,0x3000,0x180e,0x200b,0xfeff];
for (const c of cands) out.push("SELECT 1;" + C(c) + "-- c\nSELECT 2");
// mid-token EOF
out.push("SELECT 1 EN", "SELECT 1 END I", "CREATE", "BEGI", "SELECT $tag", "SELECT E'", "SELECT U&'", "SELECT U&", "SELECT X'", "SELECT 0x", "SELECT 1e", "SELECT 1.", "SELECT .1", "SELECT 1e+", "END I", "END", "END IF", "END LOOP");
// GO case/whitespace
out.push("GO\t2 SELECT 1", "Go 2 SELECT 1", "go 2 SELECT 1", "gO SELECT 1", "GO\r2 SELECT 1", "GO2 SELECT 1", "GO 2 SELECT 1");
// trailing statement made only of comment
out.push("SELECT 1;\n-- c", "SELECT 1;\n/*c*/", "SELECT 1;\n\n\n", "SELECT 1; ", "SELECT 1;\t", "SELECT 1;\n", "SELECT 1;\r\n");
writeFileSync('/workspace/probe/b7.json', JSON.stringify(out, null, 1));
